package forth

import (
	"errors"
	"strconv"
	"strings"
)

var (
	errEmptyStack = errors.New("empty stack")
	errOneValue   = errors.New("only one value on the stack")
	errDivideZero = errors.New("divide by zero")
	errUndefined  = errors.New("undefined operation")
	errIllegal    = errors.New("illegal operation")
)

// action is a single Forth operation applied to the stack.
type action func(*[]int) error

// pop2 pops the top two values, returning the second-from-top first.
func pop2(s *[]int) (int, int, error) {
	switch len(*s) {
	case 0:
		return 0, 0, errEmptyStack
	case 1:
		return 0, 0, errOneValue
	}
	b := (*s)[len(*s)-1]
	a := (*s)[len(*s)-2]
	*s = (*s)[:len(*s)-2]
	return a, b, nil
}

func binop(f func(a, b int) int) action {
	return func(s *[]int) error {
		a, b, err := pop2(s)
		if err != nil {
			return err
		}
		*s = append(*s, f(a, b))
		return nil
	}
}

var builtins = map[string]action{
	"+": binop(func(a, b int) int { return a + b }),
	"-": binop(func(a, b int) int { return a - b }),
	"*": binop(func(a, b int) int { return a * b }),
	"/": func(s *[]int) error {
		a, b, err := pop2(s)
		if err != nil {
			return err
		}
		if b == 0 {
			return errDivideZero
		}
		*s = append(*s, a/b)
		return nil
	},
	"dup": func(s *[]int) error {
		if len(*s) == 0 {
			return errEmptyStack
		}
		top := (*s)[len(*s)-1]
		*s = append(*s, top)
		return nil
	},
	"drop": func(s *[]int) error {
		if len(*s) == 0 {
			return errEmptyStack
		}
		*s = (*s)[:len(*s)-1]
		return nil
	},
	"swap": func(s *[]int) error {
		if len(*s) == 0 {
			return errEmptyStack
		}
		if len(*s) == 1 {
			return errOneValue
		}
		n := len(*s)
		(*s)[n-1], (*s)[n-2] = (*s)[n-2], (*s)[n-1]
		return nil
	},
	"over": func(s *[]int) error {
		if len(*s) == 0 {
			return errEmptyStack
		}
		if len(*s) == 1 {
			return errOneValue
		}
		second := (*s)[len(*s)-2]
		*s = append(*s, second)
		return nil
	},
}

// isNumber reports whether tok is a (possibly negative) integer:
// an optional minus sign followed by one or more ASCII digits.
func isNumber(tok string) bool {
	if tok == "" {
		return false
	}
	start := 0
	if tok[0] == '-' {
		if len(tok) == 1 {
			return false
		}
		start = 1
	}
	for i := start; i < len(tok); i++ {
		if tok[i] < '0' || tok[i] > '9' {
			return false
		}
	}
	return true
}

// resolve turns a token into an action: numbers push their value,
// words are looked up in defs (case-insensitively).
func resolve(tok string, defs map[string]action) (action, error) {
	if isNumber(tok) {
		n, _ := strconv.Atoi(tok)
		return func(s *[]int) error {
			*s = append(*s, n)
			return nil
		}, nil
	}
	a, ok := defs[strings.ToLower(tok)]
	if !ok {
		return nil, errUndefined
	}
	return a, nil
}

func Forth(input []string) ([]int, error) {
	stack := []int{}
	defs := make(map[string]action, len(builtins))
	for name, a := range builtins {
		defs[name] = a
	}

	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			tok := tokens[i]
			if tok == ":" {
				i++
				if i >= len(tokens) {
					return nil, errors.New("incomplete word definition")
				}
				name := strings.ToLower(tokens[i])
				if isNumber(name) {
					return nil, errIllegal
				}
				i++
				var body []action
				for i < len(tokens) && tokens[i] != ";" {
					a, err := resolve(tokens[i], defs)
					if err != nil {
						return nil, err
					}
					body = append(body, a)
					i++
				}
				if i >= len(tokens) {
					return nil, errors.New("incomplete word definition")
				}
				body = body // capture the resolved body as-is
				defs[name] = func(s *[]int) error {
					for _, a := range body {
						if err := a(s); err != nil {
							return err
						}
					}
					return nil
				}
				i++ // consume the ';'
				continue
			}
			a, err := resolve(tok, defs)
			if err != nil {
				return nil, err
			}
			if err := a(&stack); err != nil {
				return nil, err
			}
		}
	}
	return stack, nil
}

